-- ============================================================================
-- ΓΥΡΟΣ 1: Οι πρώτες 150 Συνταγές (1η συνταγή για κάθε νοσηλεία)
-- ============================================================================
SELECT 
    h.admission_id, 
    h.patient_amka,
    
    -- Τυχαία επιλογή ιατρού από ένα συγκεκριμένο γκρουπ
    ELT(FLOOR(1 + RAND() * 5), '80000000001', '80000000002', '80000000006', '80000000007', '80000000013') AS doctor_amka,
    
    -- ΛΙΣΤΑ ΦΑΡΜΑΚΩΝ 1
    ELT(FLOOR(1 + RAND() * 5), 'EMA/100001/2026', 'EMA/100003/2026', 'EMA/100005/2026', 'EMA/100008/2026', 'EMA/100011/2026') AS drug_ema_code,
    
    -- Οδηγία και Συχνότητα
    ELT(FLOOR(1 + RAND() * 3), '1 δισκίο μετά το φαγητό', '1 κάψουλα το πρωί', '5ml σιρόπι') AS dosage_instruction,
    ELT(FLOOR(1 + RAND() * 3), '1 φορά την ημέρα', 'Ανά 12 ώρες', 'Εφάπαξ') AS frequency,
    
    -- Ημερομηνία Έναρξης = Ημερομηνία Εισαγωγής (ακριβώς)
    DATE(h.admission_date) AS start_date,
    
    -- Ημερομηνία Λήξης = 5 ημέρες μετά την έναρξη
    DATE(DATE_ADD(h.admission_date, INTERVAL 5 DAY)) AS end_date

FROM Hospitalization h;


-- ============================================================================
-- ΓΥΡΟΣ 2: Οι επόμενες 150 Συνταγές (2η συνταγή για κάθε νοσηλεία)
-- Εγγυημένα μοναδικές λόγω διαφορετικών Φαρμάκων και +1 μέρας.
-- ============================================================================
SELECT 
    h.admission_id, 
    h.patient_amka,
    
    -- Τυχαία επιλογή ιατρού από ένα δεύτερο γκρουπ (για ποικιλία)
    ELT(FLOOR(1 + RAND() * 5), '80000000019', '80000000025', '80000000031', '80000000037', '80000000043') AS doctor_amka,
    
    -- ΛΙΣΤΑ ΦΑΡΜΑΚΩΝ 2 (Εντελώς διαφορετικά από τη Λίστα 1)
    ELT(FLOOR(1 + RAND() * 5), 'EMA/262604/2026', 'EMA/262607/2026', 'EMA/262614/2026', 'EMA/262616/2026', 'EMA/262618/2026') AS drug_ema_code,
    
    -- Οδηγία και Συχνότητα
    ELT(FLOOR(1 + RAND() * 3), '2 δισκία μετά το γεύμα', 'Ενδοφλέβια χορήγηση', 'Τοπική επάλειψη') AS dosage_instruction,
    ELT(FLOOR(1 + RAND() * 3), 'Ανά 8 ώρες', '1 φορά το βράδυ', 'Ανά 6 ώρες') AS frequency,
    
    -- Ημερομηνία Έναρξης = 1 ημέρα μετά την εισαγωγή (έτσι αποκλείεται το conflict με την ίδια μέρα)
    DATE(DATE_ADD(h.admission_date, INTERVAL 1 DAY)) AS start_date,
    
    -- Ημερομηνία Λήξης = 8 ημέρες μετά την έναρξη
    DATE(DATE_ADD(h.admission_date, INTERVAL 8 DAY)) AS end_date

FROM Hospitalization h;








SELECT 
    admission_id,
    CASE 
        WHEN admission_id % 5 = 0 THEN FLOOR(1 + RAND() * 2) -- Πολύ χαμηλές (1-2)
        WHEN admission_id % 3 = 0 THEN FLOOR(4 + RAND() * 2) -- Πολύ υψηλές (4-5)
        ELSE FLOOR(2 + RAND() * 3)                           -- Μέτριες (2-4)
    END AS medical_care,
    FLOOR(1 + RAND() * 5) AS nursing_care,
    FLOOR(1 + RAND() * 5) AS cleanliness,
    FLOOR(1 + RAND() * 5) AS food,
    CASE 
        WHEN admission_id % 3 = 0 THEN FLOOR(4 + RAND() * 2)
        ELSE FLOOR(1 + RAND() * 4)
    END AS overall_experience
FROM Hospitalization
WHERE discharge_date IS NOT NULL OR admission_id <= 500; 
-- Το admission_id <= 500 διασφαλίζει ότι θα μπουν 500 εγγραφές αν έχεις γεμίσει το Hospitalization



SET FOREIGN_KEY_CHECKS = 0;

-- =============================
--  ΔΙΟΡΘΩΣΗ ΣΧΗΜΑΤΟΣ 
-- =============================
-- Αφαιρούμε την ιατρική φροντίδα από τη γενική αξιολόγηση
--ALTER TABLE Evaluation DROP COLUMN medical_care;

-- Φτιάχνουμε τον πίνακα αξιολόγησης Ιατρών
--CREATE TABLE Doctor_Evaluation (
  --  doc_eval_id INT AUTO_INCREMENT PRIMARY KEY,
  --  admission_id INT NOT NULL,
  --  doctor_amka VARCHAR(20) NOT NULL,
  --  medical_care INT NOT NULL CHECK (medical_care BETWEEN 1 AND 5),
  --  UNIQUE (admission_id, doctor_amka), -- 1 αξιολόγηση ανά γιατρό για κάθε νοσηλεία
  --  FOREIGN KEY (admission_id) REFERENCES Hospitalization(admission_id),
  --  FOREIGN KEY (doctor_amka) REFERENCES Doctors(amka)
--);

--  Αξιολογήσεις Νοσηλείας (Hospital Evaluation) - 500 εγγραφές
SELECT 
    admission_id,
    FLOOR(1 + RAND() * 5),
    FLOOR(1 + RAND() * 5),
    FLOOR(1 + RAND() * 5),
    -- Δημιουργία ποικιλομορφίας: Κάποιες πολύ καλές, κάποιες κακές, κάποιες μέτριες
    CASE 
        WHEN admission_id % 3 = 0 THEN FLOOR(4 + RAND() * 2) 
        WHEN admission_id % 5 = 0 THEN FLOOR(1 + RAND() * 2) 
        ELSE FLOOR(2 + RAND() * 3)                           
    END AS overall_experience
FROM Hospitalization;

--  Αξιολογήσεις Ιατρών (Doctor Evaluation) - Βασισμένες στις Συνταγές
SELECT 
    p.admission_id, 
    p.doctor_amka,
    -- Δημιουργία ποικιλομορφίας στις βαθμολογίες των ιατρών
    CASE 
        WHEN p.admission_id % 4 = 0 THEN FLOOR(1 + RAND() * 2) 
        WHEN p.admission_id % 2 = 0 THEN FLOOR(4 + RAND() * 2) 
        ELSE FLOOR(2 + RAND() * 3)                           
    END AS medical_care
FROM Prescription p
GROUP BY p.admission_id, p.doctor_amka;






-- ============================================================================
-- ΒΗΜΑ 1: Εισαγωγή Νοσηλευτών (Όσοι νοσηλευτές ήταν στην ίδια βάρδια)
-- ============================================================================
SELECT 
    mp.procedure_id, 
    ss_nurse.staff_amka
FROM Medical_Procedure mp
-- Βρίσκουμε τη σωστή ημερομηνία βάρδιας (προσέχοντας τα νυχτερινά που αλλάζουν μέρα)
JOIN Shift s ON s.shift_date = CASE 
    WHEN TIME(mp.start_time) >= '23:00:00' THEN DATE_SUB(DATE(mp.start_time), INTERVAL 1 DAY)
    ELSE DATE(mp.start_time)
END
-- Βρίσκουμε το shift_id του Κύριου Ιατρού
JOIN Shift_Staff ss_main ON s.shift_id = ss_main.shift_id AND ss_main.staff_amka = mp.main_doctor_amka
-- Βρίσκουμε τους Νοσηλευτές που είχαν το ΙΔΙΟ shift_id
JOIN Shift_Staff ss_nurse ON s.shift_id = ss_nurse.shift_id
JOIN Nurses n ON ss_nurse.staff_amka = n.amka
WHERE 
    (s.shift_type = 'morning' AND TIME(mp.start_time) BETWEEN '07:00:00' AND '15:00:00') OR
    (s.shift_type = 'afternoon' AND TIME(mp.start_time) BETWEEN '15:00:00' AND '23:00:00') OR
    (s.shift_type = 'night' AND (TIME(mp.start_time) >= '23:00:00' OR TIME(mp.start_time) <= '07:00:00'));


-- ============================================================================
-- ΒΗΜΑ 2: Εισαγωγή 1 Βοηθού Ιατρού (Αν υπήρχε άλλος ιατρός στην ίδια βάρδια)
-- ============================================================================
SELECT 
    mp.procedure_id, 
    ss_doc.staff_amka
FROM Medical_Procedure mp
-- Βρίσκουμε τη σωστή ημερομηνία βάρδιας
JOIN Shift s ON s.shift_date = CASE 
    WHEN TIME(mp.start_time) >= '23:00:00' THEN DATE_SUB(DATE(mp.start_time), INTERVAL 1 DAY)
    ELSE DATE(mp.start_time)
END
-- Βρίσκουμε το shift_id του Κύριου Ιατρού
JOIN Shift_Staff ss_main ON s.shift_id = ss_main.shift_id AND ss_main.staff_amka = mp.main_doctor_amka
-- Βρίσκουμε τους ΑΛΛΟΥΣ Ιατρούς που είχαν το ΙΔΙΟ shift_id (εξαιρώντας τον εαυτό του)
JOIN Shift_Staff ss_doc ON s.shift_id = ss_doc.shift_id AND ss_doc.staff_amka != mp.main_doctor_amka
JOIN Doctors d ON ss_doc.staff_amka = d.amka
WHERE 
    (s.shift_type = 'morning' AND TIME(mp.start_time) BETWEEN '07:00:00' AND '15:00:00') OR
    (s.shift_type = 'afternoon' AND TIME(mp.start_time) BETWEEN '15:00:00' AND '23:00:00') OR
    (s.shift_type = 'night' AND (TIME(mp.start_time) >= '23:00:00' OR TIME(mp.start_time) <= '07:00:00'))
GROUP BY mp.procedure_id; -- To GROUP BY διασφαλίζει ότι θα πάρει ΜΟΝΟ ΕΝΑΝ επιπλέον γιατρό

